use vstd::prelude::*;

verus! {

spec fn spec_rotate_right(list: Seq<u32>, n: int) -> Seq<u32> {
    let len = list.len();
    if len == 0 {
        list
    } else {
        let n_mod = n % len;
        let s = len - n_mod;
        list.subrange(s, len) + list.subrange(0, s)
    }
}

fn rotate_right(list: &Vec<u32>, n: usize) -> (result: Vec<u32>)
    requires
        list.len() > 0,
    ensures
        result@ == spec_rotate_right(list@, n as int),
        result.len() == list.len(),
{
    let len = list.len();
    assert!(len > 0, "Input list must be non-empty");

    let n_mod = n % len;
    let s = len - n_mod;

    // Create a new Vec with capacity equal to len for efficiency
    let mut new_list = Vec::with_capacity(len);

    // Push suffix from index s to end
    new_list.extend_from_slice(&list[s..]);
    assert(new_list@ == list@.subrange(s as int, len as int));

    // Then push prefix from start up to s
    new_list.extend_from_slice(&list[..s]);
    assert(new_list@ == list@.subrange(s as int, len as int) + list@.subrange(0, s as int));

    new_list
}

}

